import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export const useWorkspaceStore = create(
  persist(
    (set, get) => ({
      activeTab: 'wall', // 'wall' | 'notebook' | 'notes'
      setActiveTab: (tab) => set({ activeTab: tab }),

      // --- 1. WALL TODOS ---
      todos: [
        { id: '1', text: 'Plan next sprint 🚀', completed: false, x: 60, y: 50, color: 'yellow', rotation: -2 },
        { id: '2', text: 'Buy coffee beans ☕', completed: true, x: 280, y: 90, color: 'pink', rotation: 3 },
      ],
      addTodo: (text, color = 'yellow') => set((state) => ({
        todos: [
          ...state.todos,
          {
            id: Date.now().toString(),
            text,
            completed: false,
            x: 80 + Math.random() * 80,
            y: 80 + Math.random() * 80,
            color,
            rotation: (Math.random() - 0.5) * 8
          }
        ]
      })),
      toggleTodo: (id) => set((state) => ({
        todos: state.todos.map((t) => t.id === id ? { ...t, completed: !t.completed } : t)
      })),
      deleteTodo: (id) => set((state) => ({
        todos: state.todos.filter((t) => t.id !== id)
      })),
      updateTodoPosition: (id, x, y) => set((state) => ({
        todos: state.todos.map((t) => t.id === id ? { ...t, x, y } : t)
      })),

      // --- 2. NOTEBOOK ---
      notebook: {
        isLocked: false,
        pin: '',
        isPinnedLocked: false, // agar user ne PIN se lock kiya ho
        coverType: 'leather-classic', // 'leather-classic' | 'marble' | 'obsidian'
        currentPage: 0,
        pages: [
          { id: 'p1', title: 'Welcome Page', content: 'Yeh tumhari personal digital diary hai.' }
        ]
      },
      updateNotebookPage: (pageIndex, title, content) => set((state) => {
        const pages = [...state.notebook.pages];
        pages[pageIndex] = { ...pages[pageIndex], title, content };
        return { notebook: { ...state.notebook, pages } };
      }),
      setNotebookPin: (pin) => set((state) => ({
        notebook: { ...state.notebook, pin, isPinnedLocked: true }
      })),
      unlockNotebook: () => set((state) => ({
        notebook: { ...state.notebook, isPinnedLocked: false }
      })),
      setCoverType: (coverType) => set((state) => ({
        notebook: { ...state.notebook, coverType }
      })),

      // --- 3. QUICK NOTES LIST ---
      notes: [
        { id: 'n1', title: 'Quick Thought', text: 'Always keep UI modular and clean.', createdAt: new Date().toLocaleDateString() }
      ],
      addNote: (title, text) => set((state) => ({
        notes: [{ id: Date.now().toString(), title, text, createdAt: new Date().toLocaleDateString() }, ...state.notes]
      })),
      deleteNote: (id) => set((state) => ({
        notes: state.notes.filter((n) => n.id !== id)
      })),

      // --- 4. CLOUD SYNC STATE ---
      isGoogleConnected: false,
      isSyncing: false,
      lastSyncedAt: null,
      setGoogleConnected: (status) => set({ isGoogleConnected: status }),
      setSyncing: (status) => set({ isSyncing: status }),
    }),
    {
      name: 'booktodotask_storage', // LocalStorage Key
    }
  )
);
